from playwright.sync_api import sync_playwright
BOOT='''window._q=[];window._t=0;window.requestAnimationFrame=f=>_q.push(f);window.advance=n=>{for(let i=0;i<n;i++){_t+=1000/60;const q=_q.splice(0);q.forEach(f=>f(_t));}};let seed=0;Math.random=()=>[.03,.3,.53,.71,.95][seed++%5];window.audioStarts=0;const AC=window.AudioContext||window.webkitAudioContext;if(AC){const original=AC.prototype.createOscillator;AC.prototype.createOscillator=function(){window.audioStarts++;return original.call(this);}};
window.playShift=()=>{for(let frame=0;frame<5000;frame++){const s=pizzaState();if(s.mode!=='playing')return s;if(s.customers.length){const first=s.customers[0];document.querySelector('[data-customer="'+first.id+'"]').click();if(s.cooking==='raw'){for(const topping of s.toppings)if(!first.order.toppings.includes(topping))document.querySelector('[data-topping="'+topping+'"]').click();for(const topping of first.order.toppings)if(!pizzaState().toppings.includes(topping))document.querySelector('[data-topping="'+topping+'"]').click();document.getElementById('bake').click();}else if(s.cooking==='baked')document.getElementById('serve').click();}advance(1);}return pizzaState();};'''
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 page=b.new_page(viewport={'width':1100,'height':1000});page.add_init_script(BOOT);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:8002/pizza/');page.locator('#action').click();page.wait_for_timeout(100)
 assert page.evaluate('pizzaState().customers[0].order.toppings')==['basil'];page.locator('[data-topping="corn"]').click();page.locator('#bake').click();page.evaluate('advance(90)');page.locator('#serve').click();assert page.evaluate('pizzaState().served')==0;assert page.evaluate('pizzaState().cooking')=='baked';assert '違う' in page.locator('#notice').inner_text();page.locator('#trash').click()
 page.locator('[data-topping="basil"]').click();page.locator('[data-topping="basil"]').click();assert not page.evaluate('pizzaState().toppings');page.locator('[data-topping="basil"]').click();page.locator('#bake').click();page.evaluate('advance(20)');page.locator('#pause').click();before=page.evaluate('pizzaState()');page.evaluate('advance(120)');after=page.evaluate('pizzaState()');assert before['remaining']==after['remaining'] and before['bakeLeft']==after['bakeLeft'];assert not page.locator('#modes').is_visible();page.locator('#action').click();page.evaluate('advance(70)');page.locator('#serve').click();assert page.evaluate('pizzaState().served')==1;assert page.evaluate('pizzaState().combo')==1
 page.evaluate('advance(420)');page.screenshot(path='/tmp/pizza-desktop.png');print('PASS wrong recipe, toggles, baking, frozen pause, correct service',flush=True)
 result=page.evaluate('playShift()');assert result['mode']=='finished';assert result['remaining']==0;assert result['served']>=15,result;assert result['lost']==0,result;assert result['combo']>1;assert result['best']['easy']==result['score'];print('PASS full shift',result['served'],'pizzas',result['score'],'points',flush=True)
 page.reload();assert page.evaluate('pizzaState().best.easy')==result['score'];page.locator('[data-mode="rush"]').click();page.locator('#action').click();page.wait_for_timeout(100);page.evaluate('advance(850)');assert any(c['patience']/c['max']<.25 for c in page.evaluate('pizzaState().customers'));assert page.locator('.waiting-angry').count()>0
 page.evaluate('advance(160)');assert page.evaluate('pizzaState().lost')>0;assert 'ブー' in page.locator('#notice').inner_text();assert page.evaluate('audioStarts')>=3;page.locator('#sound').click();n=page.evaluate('audioStarts');page.evaluate('advance(3000)');assert page.evaluate('audioStarts')==n;assert page.evaluate('pizzaState().mode')=='finished';assert page.evaluate('pizzaState().lost')>=5;print('PASS anger, departures, triple boo audio calls, mute, losing and saved record',flush=True)
 m=b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);m.add_init_script(BOOT);m.on('pageerror',lambda e:errors.append(str(e)));m.goto('http://127.0.0.1:8002/pizza/');m.locator('#action').tap();m.locator('[data-topping="basil"]').tap();m.locator('#bake').tap();m.evaluate('advance(90)');m.locator('#serve').tap();assert m.evaluate('pizzaState().served')==1;m.evaluate('advance(420)');m.screenshot(path='/tmp/pizza-mobile.png');assert m.evaluate('document.documentElement.scrollWidth<=innerWidth');assert not errors,errors;print('PASS mobile tap order, toppings, bake and serve, responsive layout; no JS errors');b.close()
